                raise SystemExit(f\"sequence/quality length mismatch in {path}\")
            yield rec

def rid(rec):
    token = rec[0].split(None, 1)[0]
    if token.endswith((b\"/1\", b\"/2\")):
        token = token[:-2]
    return token

def verify_unchanged_subset(original, filtered):
