use strict;
use warnings;

sub open_gz {
    my ("'$path) = @_;
    open my $fh, '"'-|', 'gzip', '-cd', "'$path or die "cannot read $path: $!'"\\n\";
    return "'$fh;
}

sub next_record {
    my ($fh, $label) = @_;
    my $first = <$fh>;
    return undef unless defined $first;
    my @rec = ($first);
    for (1..3) {
        my $line = <$fh>;
        die "partial FASTQ record in $label'"\\n\" unless defined "'$line;
        push @rec, $line;
    }
    die "invalid FASTQ structure in $label'"\\n\" unless "'$rec[0] =~ /''^'"\\@/ && "'$rec[2] =~ /''^'"\\+/;
    (my "'$seq = $rec[1]) =~ s/['"\\r\\n]+"'$//;
    (my $qual = $rec[3]) =~ s/['"\\r\\n]+"'$//;
    die "sequence/quality length mismatch in $label'"\\n\" unless length("'$seq) == length($qual);
    return '"\\@rec;
}

sub read_id {
    my ("'$rec) = @_;
    my ($id) = split /'"\\s+/, "'$rec->[0], 2;
    $id =~ s{/([12])$}{};
    return $id;
}

sub verify_subset {
    my ($original_path, $filtered_path) = @_;
    my $orig = open_gz($original_path);
    my $out = open_gz($filtered_path);
    my $source = next_record($orig, $original_path);
    my $count = 0;
    while (my $kept = next_record($out, $filtered_path)) {
        my $wanted = read_id($kept);
        while (defined $source && read_id($source) ne $wanted) {
            $source = next_record($orig, $original_path);
        }
        die "filtered ID absent or out of order: $wanted'"\\n\" unless defined "'$source;
        die "retained record modified: $wanted'"\\n\" unless join('', @"'$source) eq join('"'', @"'$kept);
        $count++;
        $source = next_record($orig, $original_path);
    }
    close $orig or die "gzip read failed for $original_path'"\\n\";
    close "'$out or die "gzip read failed for $filtered_path'"\\n\";
    return "'$count;
}

